<?php
$featuredItems = $conn->query('SELECT id, product_name, description, price, image FROM products WHERE is_available = 1 AND is_featured = 1 ORDER BY id DESC LIMIT 3')->fetchAll();
?>
<section class="py-5"><div class="container"><div class="text-center mb-4"><span class="section-tag">A few favourites</span><h2 class="section-title">Popular at Brew Haven</h2></div><div class="row g-4"><?php foreach ($featuredItems as $item): ?><div class="col-md-4"><article class="card h-100 border-0 shadow-sm rounded-4 overflow-hidden"><img src="assets/images/menu/<?= e($item['image'] ?: 'latte.jpg') ?>" alt="<?= e($item['product_name']) ?>" loading="lazy" style="height:230px;object-fit:cover"><div class="card-body d-flex flex-column"><h3 class="h5"><?= e($item['product_name']) ?></h3><p class="text-muted flex-grow-1"><?= e($item['description']) ?></p><div class="d-flex align-items-center justify-content-between"><strong>৳<?= number_format((float) $item['price'], 2) ?></strong><button class="btn btn-coffee add-cart-btn" data-id="<?= (int) $item['id'] ?>">Add to cart</button></div></div></article></div><?php endforeach; ?><?php if (!$featuredItems): ?><div class="col-12 text-center text-muted">New favourites are on the way.</div><?php endif; ?></div><div class="text-center mt-4"><a class="btn btn-outline-dark" href="menu.php">View full menu</a></div></div></section>
